from datetime import date, timedelta
feriados = {date(2026,11,20), date(2026,12,8), date(2026,12,24), date(2026,12,25),
            date(2026,12,31), date(2027,1,1), date(2027,2,8), date(2027,2,9)}
recesso = (date(2026,12,20), date(2027,1,20))
def du(d):
    return d.weekday()<5 and d not in feriados and not (recesso[0]<=d<=recesso[1])
def conta(inicio,n):
    dias,d=[],inicio
    while len(dias)<n:
        if du(d): dias.append(d)
        d+=timedelta(days=1)
    return dias
f=lambda d:d.strftime("%d/%m/%Y (%a)")
# cenário EM DOBRO (se o caput do art. 229 valesse):
c30=conta(date(2026,11,24),30)
a30=conta(date(2026,12,14),30)
print("DOBRO - contestaçao 30 d/u a partir de 24/11/2026:")
for i,x in enumerate(c30,1): print(f"  {i:2d}: {f(x)}")
print("DOBRO - apelacao 30 d/u a partir de 14/12/2026:")
for i,x in enumerate(a30,1): print(f"  {i:2d}: {f(x)}")
EOF
